        if order.get("items"):
            weight = sum(i["weight"] for i in order["items"])
            if weight <= 30:
                dest = order.get("destination")
                if dest in ("domestic", "international"):
                    base = 5.0 if dest == "domestic" else 15.0
                    return {"weight": weight, "cost": round(base + 0.5 * weight, 2)}
                else:
                    raise ValueError("unknown destination")
            else:
                raise ValueError("order too heavy")
        else:
            raise ValueError("order has no items")
    else:
        raise ValueError("order is required")

