import pytest

from quotes import shipping_quote


def test_domestic_quote():
    order = {"items": [{"weight": 10}, {"weight": 10}], "destination": "domestic"}
    assert shipping_quote(order) == {"weight": 20, "cost": 15.0}


def test_international_quote():
    order = {"items": [{"weight": 4}], "destination": "international"}
    assert shipping_quote(order) == {"weight": 4, "cost": 17.0}


def test_weight_exactly_at_limit_is_allowed():
    order = {"items": [{"weight": 30}], "destination": "domestic"}
    assert shipping_quote(order)["weight"] == 30


def test_rejections_keep_exact_messages():
    with pytest.raises(ValueError, match="order is required"):
        shipping_quote(None)
    with pytest.raises(ValueError, match="order has no items"):
        shipping_quote({"items": []})
    with pytest.raises(ValueError, match="order too heavy"):
        shipping_quote({"items": [{"weight": 31}], "destination": "domestic"})
    with pytest.raises(ValueError, match="unknown destination"):
        shipping_quote({"items": [{"weight": 1}], "destination": "moon"})

